package capture

import (
	"bytes"
	"testing"

	blst "github.com/supranational/blst/bindings/go"
)

func TestJRSignatureRoundtripAndTampering(t *testing.T) {
	var sk Sk
	var vk Vk
	if err := GenerateKeyPair(&sk, &vk); err != nil {
		t.Fatal(err)
	}
	defer sk.Clear()

	// Real random group message, including a point generated by HashToG1.
	m := RandomG1Point(new(blst.P1))
	var sig Signature
	if err := Sign(&sk, m, &sig); err != nil {
		t.Fatal(err)
	}
	ok, err := Verify(m.ToAffine(), &sig, &vk)
	if err != nil || ok != 1 {
		t.Fatalf("honest JR signature rejected: %d %v", ok, err)
	}

	rawVK := make([]byte, VkCompressedSize)
	originalVK := vk
	if err := vk.CompressToAndClear(rawVK); err != nil {
		t.Fatal(err)
	}
	if vk.IsSet() {
		t.Fatal("VK wasn't cleared")
	}
	var decodedVK Vk
	if err := decodedVK.UncompressAndClear(rawVK); err != nil {
		t.Fatal(err)
	}
	if !decodedVK.IsSet() {
		t.Fatal("decoded VK not set")
	}
	for _, b := range rawVK {
		if b != 0 {
			t.Fatal("VK byte buffer not cleared")
		}
	}
	if !captureEqualVK(&originalVK, &decodedVK) {
		t.Fatal("VK roundtrip mismatch")
	}

	rawSig := make([]byte, SignatureCompressedSize)
	originalSig := sig
	if err := sig.CompressToAndClear(rawSig); err != nil {
		t.Fatal(err)
	}
	if sig.IsSet() {
		t.Fatal("signature wasn't cleared")
	}
	var decodedSig Signature
	if err := decodedSig.UncompressAndClear(rawSig); err != nil {
		t.Fatal(err)
	}
	for _, b := range rawSig {
		if b != 0 {
			t.Fatal("signature byte buffer not cleared")
		}
	}
	ok, err = Verify(m.ToAffine(), &decodedSig, &decodedVK)
	if err != nil || ok != 1 {
		t.Fatalf("signature roundtrip rejected: %d %v", ok, err)
	}
	if !originalSig.rho.Equals(&decodedSig.rho) || !originalSig.pi.Equals(&decodedSig.pi) || !originalSig.tau.Equals(&decodedSig.tau) {
		t.Fatal("signature changed after roundtrip")
	}

	tests := []struct {
		name   string
		modify func(*Signature)
	}{
		{"rho", func(s *Signature) { p := gsP1FromAff(&s.rho); p.AddAssign(blst.P1Generator()); s.rho = *p.ToAffine() }},
		{"rhoHat", func(s *Signature) {
			p := gsP1FromAff(&s.rhoHat)
			p.AddAssign(blst.P1Generator())
			s.rhoHat = *p.ToAffine()
		}},
		{"psi", func(s *Signature) { p := gsP1FromAff(&s.psi); p.AddAssign(blst.P1Generator()); s.psi = *p.ToAffine() }},
		{"gamma", func(s *Signature) {
			p := gsP1FromAff(&s.gamma)
			p.AddAssign(blst.P1Generator())
			s.gamma = *p.ToAffine()
		}},
		{"pi", func(s *Signature) { p := gsP1FromAff(&s.pi); p.AddAssign(blst.P1Generator()); s.pi = *p.ToAffine() }},
		{"tau", func(s *Signature) { p := gsP2FromAff(&s.tau); p.AddAssign(blst.P2Generator()); s.tau = *p.ToAffine() }},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			tampered := decodedSig
			tc.modify(&tampered)
			accepted, err := Verify(m.ToAffine(), &tampered, &decodedVK)
			if err == nil && accepted == 1 {
				t.Fatal("modified JR signature accepted")
			}
		})
	}
	other := RandomG1Point(new(blst.P1)).ToAffine()
	ok, err = Verify(other, &decodedSig, &decodedVK)
	if err == nil && ok == 1 {
		t.Fatal("JR signature verifies different message")
	}

	// A failed decoding must clear the old signature and must consume input.
	invalid := []byte{0}
	if err := decodedSig.UncompressAndClear(invalid); err == nil {
		t.Fatal("malformed JR signature decoded")
	}
	if decodedSig.IsSet() {
		t.Fatal("failed JR decoder kept old signature")
	}
	if !bytes.Equal(invalid, []byte{0}) {
		t.Fatal("invalid buffer was not cleared")
	}
}

func TestJRCAKeysNotInterchangeable(t *testing.T) {
	var sk1, sk2 Sk
	var vk1, vk2 Vk
	if err := GenerateKeyPair(&sk1, &vk1); err != nil {
		t.Fatal(err)
	}
	if err := GenerateKeyPair(&sk2, &vk2); err != nil {
		t.Fatal(err)
	}
	defer sk1.Clear()
	defer sk2.Clear()
	m := RandomG1Point(new(blst.P1))
	var sig Signature
	if err := Sign(&sk1, m, &sig); err != nil {
		t.Fatal(err)
	}
	ok, err := Verify(m.ToAffine(), &sig, &vk2)
	if err == nil && ok == 1 {
		t.Fatal("JR signature accepted with other CA")
	}
}

func BenchmarkJRSign(b *testing.B) {
	var sk Sk
	var vk Vk
	if err := GenerateKeyPair(&sk, &vk); err != nil {
		b.Fatal(err)
	}
	defer sk.Clear()
	m := RandomG1Point(new(blst.P1))
	b.ReportAllocs()
	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		var sig Signature
		if err := Sign(&sk, m, &sig); err != nil {
			b.Fatal(err)
		}
	}
}
func BenchmarkJRVerify(b *testing.B) {
	var sk Sk
	var vk Vk
	if err := GenerateKeyPair(&sk, &vk); err != nil {
		b.Fatal(err)
	}
	defer sk.Clear()
	m := RandomG1Point(new(blst.P1))
	var sig Signature
	if err := Sign(&sk, m, &sig); err != nil {
		b.Fatal(err)
	}
	b.ReportAllocs()
	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		ok, err := Verify(m.ToAffine(), &sig, &vk)
		if err != nil || ok != 1 {
			b.Fatal("JR verifier rejected")
		}
	}
}
